class Solution {
    public boolean isValid(String s) {
        String remaining = s;
        boolean removed;
        do {
            removed = false;
            StringBuilder next = new StringBuilder();
            int index = 0;
            while (index < remaining.length()) {
                if (index + 1 < remaining.length()
                        && matches(remaining.charAt(index), remaining.charAt(index + 1))) {
                    index += 2;
                    removed = true;
                } else {
                    next.append(remaining.charAt(index));
                    index++;
                }
            }
            remaining = next.toString();
        } while (removed);
        return remaining.isEmpty();
    }

    private boolean matches(char open, char close) {
        return (open == '(' && close == ')')
                || (open == '[' && close == ']')
                || (open == '{' && close == '}');
    }
}

