class Solution {
    public boolean isValid(String s) {
        char[] open = new char[s.length()];
        int size = 0;
        for (int index = 0; index < s.length(); index++) {
            char current = s.charAt(index);
            if (current == '(' || current == '[' || current == '{') {
                open[size++] = current;
            } else {
                if (size == 0) {
                    return false;
                }
                char previous = open[--size];
                if ((current == ')' && previous != '(')
                        || (current == ']' && previous != '[')
                        || (current == '}' && previous != '{')) {
                    return false;
                }
            }
        }
        return size == 0;
    }
}
